CREATE TEMPORARY VIEW dim_high_gmv_cate_${grass_region_without_quote} AS
SELECT
    transform(split(trim(translate(category, '[]', '')), ','), x->trim(x)) AS high_gmv_category
FROM 
(   
    SELECT
        *
        ,row_number() over (partition by grass_region order by update_date desc) as rn
    FROM 
        srdi_mart.dim_sr_data_warehouse_high_gmv_category
    WHERE
        grass_region = ${grass_region}
)
WHERE
    rn = 1
;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_item_${grass_region_without_quote} AS
SELECT
    item_id
    ,level1_global_be_category
FROM
    srdi_mart.dim_sr_data_warehouse_item
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_order_${grass_region_without_quote} AS
SELECT 
    COALESCE(is_ads, false) AS is_ads
    ,order_id
    ,a.item_id 
    ,if(array_contains(high_gmv_category, level1_global_be_category), 'high gmv', 'low gmv') AS category_tag
    ,array_union(array_union(build_scenario_tags(reporting_business_line,reporting_module, reporting_object, null,algo_tag, null),
        build_scenario_tags(source1_reporting_business_line,source1_reporting_module, source1_reporting_object, null, source1_algo_tag, null)), 
        build_scenario_tags(source2_reporting_business_line,source2_reporting_module, source2_reporting_object, null, source2_algo_tag, null) ) 
    AS feature_groups
	,sum(place_order_gmv) as gmv
    ,sum(pc2_gmv) as pc2_gmv
FROM 
    srdi_mart.dwd_sr_data_warehouse_platform a 
    LEFT JOIN dim_item_${grass_region_without_quote} b 
        ON a.item_id = b.item_id
    CROSS JOIN dim_high_gmv_cate_${grass_region_without_quote} c
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND operation = 'order'
GROUP BY 
    1,2,3,4,5
UNION ALL
SELECT 
    COALESCE(is_ads, false) AS is_ads
    ,order_id
    ,a.item_id 
    ,if(array_contains(high_gmv_category, level1_global_be_category), 'high gmv', 'low gmv') AS category_tag
    ,ARRAY('__ALL__') AS feature_groups
	,sum(place_order_gmv) as gmv
    ,sum(pc2_gmv) as pc2_gmv
FROM 
    srdi_mart.dwd_sr_data_warehouse_platform a 
    LEFT JOIN dim_item_${grass_region_without_quote} b 
        ON a.item_id = b.item_id
    CROSS JOIN dim_high_gmv_cate_${grass_region_without_quote} c
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND operation = 'order'
GROUP BY 
    1,2,3,4,5;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dim_sr_data_warehouse_category_gmv_outlier
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT 
    feature_group
    ,COALESCE(CAST(is_ads AS STRING) ,'__ALL__') AS is_ads
    ,category_tag
    ,approx_percentile(if(gmv>0,gmv, NULL), 0.995) as gmv_995pct
    ,approx_percentile(if(pc2_gmv>0,pc2_gmv, NULL), 0.995) as pc2_gmv_995pct
FROM
    dws_order_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(feature_groups) AS feature_group
GROUP BY 
    feature_group
    ,category_tag
    ,cube(is_ads);
